    for(const auto& row:rows) {
        std::cout<<"PUBLIC_BACKUP_API_ROW phase="<<phase<<" table="<<table<<" id="<<row.id<<" rid="<<row.rid<<" nulls=";
        for(bool null:row.nulls)std::cout<<char(null?'1':'0');std::cout<<" cells_hex=";
        for(size_t i=0;i<row.cells.size();++i){if(i)std::cout<<',';std::cout<<hex(row.cells[i]);}std::cout<<'\n';
    }
}
void createNullProbe(StorageEngine& engine) {
