    TableSchema schema;schema.tablename="backup_null_probe";schema.formatVersion=DATA_FILE_FORMAT_VERSION;
    schema.append(makeIntColumn("id",false,4,true));schema.append(makeIntColumn("n",true,4));schema.append(makeTextColumn("t",true));
    require(engine.createTable("info",schema)==DBStatus::OK,"actual NULL probe table");
    const std::vector<StorageEngine::SqlRow> inputs={
        {{"id","1"},{"n",std::nullopt},{"t",std::nullopt}},
        {{"id","2"},{"n","0"},{"t",""}},
        {{"id","3"},{"n","-2147483648"},{"t","NULL"}},
        {{"id","4"},{"n","2147483647"},{"t",std::string(6000,'T')+"λ"}}};
    for(const auto& row:inputs)require(engine.insertRow("info","backup_null_probe",row)==DBStatus::OK,"actual NULL/empty/literalNULL/TOAST input");
}
void checkNullProbe(const std::vector<Row>& rows) {
    require(rows.size()==4,"actual probe count");
    const std::vector<std::vector<std::optional<std::string>>> expected={
        {{"1"},{},{}},{{"2"},{"0"},{""}},{{"3"},{"-2147483648"},{"NULL"}},{{"4"},{"2147483647"},{std::string(6000,'T')+"λ"}}};
    for(size_t i=0;i<4;++i){require(rows[i].id==int(i+1)&&rows[i].cells.size()==3,"actual probe widths/ids");
        for(size_t c=0;c<3;++c)require(rows[i].nulls[c]==!expected[i][c] && (!expected[i][c]||rows[i].cells[c]==*expected[i][c]),"independent probe full values/NULLs");}
