        std::vector<Row> probeBefore;
        if(seed){require(nullProbe,"real NULL preparation required");createNullProbe(engine);const auto probe=snapshot(engine,"backup_null_probe");checkNullProbe(probe);output("seeded","backup_null_probe",probe);
            std::cout<<"PUBLIC_BACKUP_API_COMPLETE operation=seed-null primary_rows=1000 primary_cells=4000 probe_rows=4 exact_values_RID_NULL=1 failures=0\n";return 0;}
        if(create && nullProbe){probeBefore=snapshot(engine,"backup_null_probe");checkNullProbe(probeBefore);output("before","backup_null_probe",probeBefore);}
        std::cout.flush();
