            if(timed){const auto w=std::chrono::steady_clock::now();const auto p=clockNs(CLOCK_PROCESS_CPUTIME_ID),t=clockNs(CLOCK_THREAD_CPUTIME_ID);
                result=engine.physicalBackup("info",image.string());
                thread=clockNs(CLOCK_THREAD_CPUTIME_ID)-t;process=clockNs(CLOCK_PROCESS_CPUTIME_ID)-p;wall=std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-w).count();}
            else result=engine.physicalBackup("info",image.string());
