            require(result,"actual durable physicalBackup result");const auto after=snapshot(engine,"bench_rows");checkPrimary(after);require(same(before,after),"source full rows/RIDs/NULL unchanged");output("after","bench_rows",after);
            if(nullProbe){const auto probe=snapshot(engine,"backup_null_probe");checkNullProbe(probe);require(same(probeBefore,probe),"source NULL probe actual RID/value preserved");output("after","backup_null_probe",probe);}
        } else {
