P=HERE.parent
ROOT=P.parents[1]
def sha(path): return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def utc(): return datetime.datetime.now(datetime.timezone.utc).isoformat()
def identity(pid):
    p=Path('/proc')/str(pid); s=(p/'stat').read_text(); return {'pid':pid,'start_ticks':s[s.rfind(')')+2:].split()[19],'exe':str((p/'exe').resolve()),'pgid':os.getpgid(pid)}
