            p=Path(base)/name
            if p.is_symlink():raise ValueError('symlink in owned input/image')
            directories.append(p.relative_to(root).as_posix())
        for name in fs:
            p=Path(base)/name
            if p.is_symlink()or not p.is_file():raise ValueError('nonregular owned input/image')
            info=p.stat();files[p.relative_to(root).as_posix()]={'size':info.st_size,'sha256':sha(p),'mode':stat.S_IMODE(info.st_mode),'allocated_bytes':info.st_blocks*512}
