    inv=inventory(image);text=(image/'.dbms_backup_manifest').read_text(); lines=text.splitlines()
    assert lines[:2]==['DBMS_PHYSICAL_BACKUP_MANIFEST_V2','S\t696e666f']
    assert (image/'.dbms_physical_backup').read_bytes()==b'DBMS_PHYSICAL_BACKUP_V3\n'
